// Scope: common
package main

import (
	_ "unsafe"

	"github.com/xgo-dev/llgo/runtime/abi"
)

//go:linkname cstr llgo.cstr
func cstr(string) *int8

//go:linkname printf C.printf
func printf(format *int8, __llgo_va_list ...any) int32

func Basic(kind abi.Kind) *abi.Type {
	return basicTypes[kind]
}

func basicType(kind abi.Kind) *abi.Type {
	return &abi.Type{
		Size_: sizeBasicTypes[kind],
		Hash:  uint32(kind),
		Kind_: uint8(kind),
	}
}

var (
	basicTypes = [...]*abi.Type{
		abi.String: basicType(abi.String),
	}
	sizeBasicTypes = [...]uintptr{
		abi.String: 16,
	}
)

func main() {
	t := Basic(abi.String)
	printf(cstr("Kind: %d, Size: %d\n"), int(t.Kind_), t.Size_)
}

